oCharts,ch=>`<div class="item simpleTreeItem ${state.activeFile===`chart:${ch.id}`?'active':''}" data-type="simple-chart" data-id="${esc(ch.id)}"><div class="materialsIcon code">CH</div><div class="itemName">${esc(ch.title)}<div class="itemMeta">${esc(ch.chartType)} · ${esc(ch.aggregation)} · score ${esc(ch.score)}</div></div></div>`);
